INSERT INTO b_portal_supplement (
    portal_id, round_no, status, official_id, requested_at,
    customer_submitted_at, submitted_to_mara_at, mara_id, reviewed_at, review_remark,
    reopen_at, reopen_remark
) VALUES (
    #{portalId}, #{roundNo}, #{status}, #{officialId}, #{requestedAt},
    #{customerSubmittedAt}, #{submittedToMaraAt}, #{maraId}, #{reviewedAt}, #{reviewRemark},
    #{reopenAt}, #{reopenRemark}
