mapper.select:
SELECT ps.id, ps.portal_id AS portalId, ps.round_no AS roundNo, ps.status, ps.official_id AS officialId, ps.requested_at AS requestedAt, ps.customer_submitted_at AS customerSubmittedAt, ps.submitted_to_mara_at AS submittedToMaraAt, ps.mara_id AS maraId, ps.reviewed_at AS reviewedAt, ps.review_remark AS reviewRemark, ps.reopen_at AS reopenAt, ps.reopen_remark AS reopenRemark, ps.gmt_create AS gmtCreate, ps.gmt_modify AS gmtModify FROM b_portal_supplement ps WHERE ps.id = #{id}
AND ps.portal_id = #{portalId}
AND EXISTS ( SELECT 1 FROM b_portal_list pl WHERE pl.id = ps.portal_id AND pl.name LIKE CONCAT('%', #{name}, '%') )

SELECT ps.id, ps.portal_id AS portalId, ps.round_no AS roundNo, ps.status,
       ps.official_id AS officialId, ps.requested_at AS requestedAt,
       ps.customer_submitted_at AS customerSubmittedAt,
       ps.submitted_to_mara_at AS submittedToMaraAt, ps.mara_id AS maraId,
       ps.reviewed_at AS reviewedAt, ps.review_remark AS reviewRemark,
       ps.reopen_at AS reopenAt, ps.reopen_remark AS reopenRemark,
       ps.gmt_create AS gmtCreate, ps.gmt_modify AS gmtModify
FROM b_portal_supplement ps
WHERE 1 = 1

    AND ps.id = #{id}


    AND ps.portal_id = #{portalId}


    AND ps.mara_id = #{maraId}


    AND ps.official_id = #{officialId}


    AND ps.status = #{strState}


    AND ps.status IN ('REVIEWING', 'REJECTED', 'APPROVED')


    AND EXISTS (
        SELECT 1 FROM b_portal_list pl
        WHERE pl.id = ps.portal_id AND pl.name LIKE CONCAT('%', #{name}, '%')
    )

ORDER BY ps.round_no DESC, ps.id DESC
LIMIT #{offset}, #{rows}

SELECT COUNT(*) FROM b_portal_supplement ps
WHERE 1 = 1

    AND ps.id = #{id}


    AND ps.portal_id = #{portalId}


    AND ps.mara_id = #{maraId}


    AND ps.official_id = #{officialId}


    AND ps.status = #{strState}


    AND ps.status IN ('REVIEWING', 'REJECTED', 'APPROVED')


    AND EXISTS (
        SELECT 1 FROM b_portal_list pl
        WHERE pl.id = ps.portal_id AND pl.name LIKE CONCAT('%', #{name}, '%')
    )

